server {
    listen 80;
    server_name arsify.upshalter.com;

    # Security headers
    add_header X-Frame-Options "SAMEORIGIN" always;
    add_header X-Content-Type-Options "nosniff" always;
    add_header X-XSS-Protection "1; mode=block" always;

    # Public landing page / status
    location = / {
        return 200 "🚀 Arsify OS × Upshalter Collaboration Portal\n\nVersion: 3.0.0 (Upgrading to v3.1.0 on 9 Mei 2026)\nStatus: Online\nOllama: Connected\n\nFor API access: POST /v1/chat/completions\nFor health check: GET /health\n\n---\nUpshalter Reference Implementation\nupshalter.com/arsify";
        add_header Content-Type text/plain;
    }

    # Health endpoint (public)
    location /health {
        proxy_pass http://127.0.0.1:8000/health;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    }

    # OpenAI-compatible API (public)
    location /v1/ {
        proxy_pass http://127.0.0.1:8000/v1/;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;

        # Increase timeout untuk streaming
        proxy_read_timeout 300s;
        proxy_connect_timeout 75s;
    }

    # Deny admin/control dari public internet
    location /admin {
        return 403 "Access denied: Admin panel only available via Tailscale (100.109.101.58)";
    }

    location /control {
        return 403 "Access denied: Control panel only available via Tailscale";
    }

    location /docs {
        proxy_pass http://127.0.0.1:8000/docs;
        proxy_set_header Host $host;
    }
}", "exit_code": 0, "error": null}

